const defaultHomeBanner='assets/home-hero-default.png?v=4';
const defaultMobileHomeBanner='assets/home-hero-mobile-default.png?v=2';
let homeBannerDraft={};
try{homeBannerDraft=JSON.parse(localStorage.getItem('goodsHomeBanner')||'{}')||{};}catch{homeBannerDraft={};}
function renderHomeBannerEditor(){
 const desktop=homeBannerDraft.desktop||defaultHomeBanner,mobile=homeBannerDraft.mobile||defaultMobileHomeBanner;
 $('homeBannerDesktopPreview').src=desktop;$('homeBannerDesktopName').textContent=homeBannerDraft.desktopName||'기본 배너';
 $('homeBannerMobilePreview').hidden=false;$('homeBannerMobileFallback').hidden=true;$('homeBannerMobilePreview').src=mobile;
 $('homeBannerMobileName').textContent=homeBannerDraft.mobileName||'기본 모바일 배너';$('removeHomeBannerMobile').disabled=!homeBannerDraft.mobile;
}
function readHomeBannerFile(file,target){
 const status=$('homeBannerStatus');status.textContent='';status.classList.remove('is-error');
 if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status.textContent='JPG, PNG, WebP 이미지만 등록할 수 있습니다.';status.classList.add('is-error');return;}
 if(file.size>4*1024*1024){status.textContent='이미지는 파일당 4MB 이하로 등록해 주세요.';status.classList.add('is-error');return;}
 const reader=new FileReader();reader.onload=()=>{homeBannerDraft[target]=reader.result;homeBannerDraft[target+'Name']=file.name;renderHomeBannerEditor();status.textContent='미리보기에 반영했습니다. 배너 저장을 눌러 적용해 주세요.';};reader.onerror=()=>{status.textContent='이미지를 읽지 못했습니다. 다른 파일을 선택해 주세요.';status.classList.add('is-error');};reader.readAsDataURL(file);
}
function bindHomeBannerEditor(){
 renderHomeBannerEditor();
 $('homeBannerDesktopFile').onchange=event=>{readHomeBannerFile(event.target.files[0],'desktop');event.target.value='';};
 $('homeBannerMobileFile').onchange=event=>{readHomeBannerFile(event.target.files[0],'mobile');event.target.value='';};
 $('removeHomeBannerDesktop').onclick=()=>{delete homeBannerDraft.desktop;delete homeBannerDraft.desktopName;renderHomeBannerEditor();$('homeBannerStatus').textContent='기본 배너로 되돌렸습니다. 저장을 눌러 적용해 주세요.';};
 $('removeHomeBannerMobile').onclick=()=>{delete homeBannerDraft.mobile;delete homeBannerDraft.mobileName;renderHomeBannerEditor();$('homeBannerStatus').textContent='기본 모바일 배너로 되돌렸습니다. 저장을 눌러 적용해 주세요.';};
 $('saveHomeBanner').onclick=()=>{const status=$('homeBannerStatus');try{localStorage.setItem('goodsHomeBanner',JSON.stringify({...homeBannerDraft,updatedAt:Date.now()}));status.classList.remove('is-error');status.textContent='메인 배너 이미지를 저장했습니다.';}catch{status.textContent='저장 공간이 부족합니다. 이미지 용량을 줄인 뒤 다시 시도해 주세요.';status.classList.add('is-error');}};
}
function bindShippingGuide(){
 const guide=document.querySelector('.shipping-guide'),content=guide?.querySelector(':scope>div');if(!guide||!content)return;
 const toggle=document.createElement('button');toggle.type='button';toggle.className='shipping-guide-toggle';toggle.setAttribute('aria-controls','shippingGuideDetails');content.id='shippingGuideDetails';
 const setCollapsed=collapsed=>{guide.classList.toggle('is-collapsed',collapsed);content.hidden=collapsed;toggle.setAttribute('aria-expanded',String(!collapsed));toggle.textContent=collapsed?'안내 펼치기':'안내 접기';};
 guide.querySelector('h2').insertAdjacentElement('afterend',toggle);setCollapsed(localStorage.getItem('shippingGuideCollapsed')==='true');
 toggle.onclick=()=>{const collapsed=!guide.classList.contains('is-collapsed');setCollapsed(collapsed);localStorage.setItem('shippingGuideCollapsed',String(collapsed));};
}
let showOperationTab=()=>{};
function initOperationsTabs(){
 const nav=document.querySelector('.operations-jump-nav');if(!nav)return;
 document.querySelector('#operationProducts>.operation-section-heading')?.remove();
 const bannerSaveButton=$('saveHomeBanner'),headingActions=document.querySelector('#operationsView .heading-actions');if(bannerSaveButton&&headingActions){headingActions.append(bannerSaveButton);bannerSaveButton.hidden=true;}document.querySelector('.home-banner-admin-heading')?.remove();
 const productTab=nav.querySelector('[data-operation-tab="operationProducts"]');if(productTab)nav.prepend(productTab);
 const links=[...nav.querySelectorAll('[data-operation-tab]')],panels=links.map(link=>document.getElementById(link.dataset.operationTab)).filter(Boolean),validIds=new Set(panels.map(panel=>panel.id));
 showOperationTab=(requestedId,{updateHash=true,focus=false}={})=>{const id=validIds.has(requestedId)?requestedId:'operationProducts';links.forEach(link=>{const active=link.dataset.operationTab===id;link.classList.toggle('active',active);link.setAttribute('aria-selected',String(active));link.tabIndex=active?0:-1;if(active&&focus)link.focus();});panels.forEach(panel=>panel.hidden=panel.id!==id);$('addGoods').hidden=id!=='operationProducts';$('saveHomeBanner').hidden=id!=='operationBanner';$('saveStoreSettings').hidden=id!=='operationSettings';if(updateHash)history.replaceState(null,'','#'+id);};
 links.forEach((link,index)=>{link.addEventListener('click',event=>{event.preventDefault();showOperationTab(link.dataset.operationTab);});link.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let next=index;if(event.key==='ArrowLeft')next=(index-1+links.length)%links.length;if(event.key==='ArrowRight')next=(index+1)%links.length;if(event.key==='Home')next=0;if(event.key==='End')next=links.length-1;showOperationTab(links[next].dataset.operationTab,{focus:true});});});
 showOperationTab(location.hash.slice(1),{updateHash:validIds.has(location.hash.slice(1))});
 window.addEventListener('hashchange',()=>{if(validIds.has(location.hash.slice(1)))showOperationTab(location.hash.slice(1),{updateHash:false});});
}
function notify(message){$('adminStatus').textContent=message;}
function updatePendingCount(){const count=orderData.filter(order=>order.status==='출고 대기').length,badge=$('pendingCount');badge.textContent=count;badge.hidden=count<1;}
function filteredOrders(){const keyword=$('keyword').value.trim().toLowerCase(),payment=$('paymentFilter').value,ship=$('shippingFilter').value;return orderData.filter(o=>{const date=o.createdAt?new Date(o.createdAt):null;const day=date?`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`:'';return (salesTab!=='shipping'||(shippingStage==='pending'?o.status==='출고 대기':['출고 완료','배송 완료'].includes(o.status)))&&(!keyword||[o.number,o.name,o.phone,o.recipient].join(' ').toLowerCase().includes(keyword))&&(!payment||(payment==='cancelled'?o.status==='전체 취소':o.status!=='전체 취소'))&&(!ship||o.status===ship)&&(!$('startDate').value||day>=$('startDate').value)&&(!$('endDate').value||day<=$('endDate').value);});}
function trackingLookupUrl(carrier,trackingNumber){
 const number=String(trackingNumber||'').replace(/[^0-9A-Za-z]/g,'');
 const officialUrls={
  'CJ대한통운':value=>`https://www.cjlogistics.com/ko/tool/parcel/newTracking?gnbInvcNo=${encodeURIComponent(value)}`,
  '한진택배':value=>`https://www.hanjin.com/kor/CMS/DeliveryMgr/WaybillResult.do?mCode=MN038&schLang=KR&wblnum=${encodeURIComponent(value)}&wblnumText=`,
  '롯데택배':value=>`https://www.lotteglogis.com/home/reservation/tracking/invoiceView?InvNo=${encodeURIComponent(value)}`,
  '우체국택배':value=>`https://service.epost.go.kr/trace.RetrieveRegiPrclDeliv.postal?sid1=${encodeURIComponent(value)}`,
  '로젠택배':value=>`https://www.ilogen.com/web/personal/tkSearch?slipno=${encodeURIComponent(value)}`,
  '경동택배':value=>`https://kdexp.com/service/delivery/etc/delivery.do?barcode=${encodeURIComponent(value)}`,
  '대신택배':value=>`https://www.ds3211.co.kr/freight/internalFreightSearch.ht?billno=${encodeURIComponent(value)}`,
  '일양로지스':value=>`https://www.ilyanglogis.com/functionality/tracking_result.asp?hawb_no=${encodeURIComponent(value)}`,
  '천일택배':value=>`https://www.chunil.co.kr/HTrace/HTrace.jsp?transNo=${encodeURIComponent(value)}`,
  '합동택배':value=>`https://hdexp.co.kr/delivery_search.hd?barcode=${encodeURIComponent(value)}`,
  'CU 편의점택배':value=>`https://www.cupost.co.kr/postbox/delivery/localResult.cupost?invoice_no=${encodeURIComponent(value)}`,
  'GS Postbox':value=>`https://www.cvsnet.co.kr/invoice/tracking.do?invoice_no=${encodeURIComponent(value)}`,
  'DHL':value=>`https://www.dhl.com/kr-ko/home/tracking/tracking-express.html?submit=1&tracking-id=${encodeURIComponent(value)}`,
  'FedEx':value=>`https://www.fedex.com/fedextrack/?trknbr=${encodeURIComponent(value)}`,
  'UPS':value=>`https://www.ups.com/track?loc=ko_KR&tracknum=${encodeURIComponent(value)}`
 };
 if(officialUrls[carrier])return officialUrls[carrier](number);
 const params=new URLSearchParams({query:`${carrier||'택배'} ${number} 배송조회`.trim()});
 return `https://search.naver.com/search.naver?${params.toString()}`;
}
function trackingLookupTitle(carrier){return carrierNames.includes(carrier)&&carrier!=='기타 택배사'?`${carrier} 공식 배송조회`:'네이버 배송조회';}
function invoiceCell(o){
 if(salesTab!=='shipping')return o.trackingNumber?`<div class="invoice-readonly"><span>${esc(o.carrier||'택배사 미등록')}</span><b>${esc(o.trackingNumber)}</b><a class="invoice-lookup" href="${esc(trackingLookupUrl(o.carrier,o.trackingNumber))}" target="_blank" rel="noopener noreferrer" title="${esc(trackingLookupTitle(o.carrier))}">조회 ↗</a></div>`:`<span class="invoice-status ${o.status==='전체 취소'?'invoice-cancelled':''}">${o.status==='전체 취소'?'취소된 주문':'미등록'}</span>`;
 if(o.status==='전체 취소')return '<span class="invoice-status invoice-cancelled">취소된 주문</span>';
 if(!['출고 대기','출고 완료','배송 완료'].includes(o.status))return '<span class="invoice-status">송장 등록 불가</span>';
 return `<div class="invoice-inline"><select class="invoice-carrier" aria-label="${esc(o.number)} 택배사">${carrierNames.map(c=>`<option ${c===(o.carrier||$('defaultCarrier').value)?'selected':''}>${c}</option>`).join('')}</select><div class="invoice-entry"><input class="tracking-input" inputmode="text" aria-label="${esc(o.number)} 송장번호" placeholder="송장번호 입력" value="${esc(o.trackingNumber||'')}"><button class="invoice-save" aria-label="${esc(o.number)} 송장 ${o.trackingNumber?'수정':'등록'}">${o.trackingNumber?'수정':'등록'}</button>${o.trackingNumber?`<a class="invoice-lookup" href="${esc(trackingLookupUrl(o.carrier,o.trackingNumber))}" target="_blank" rel="noopener noreferrer" title="${esc(trackingLookupTitle(o.carrier))}">조회 ↗</a>`:''}</div><p class="invoice-row-error" role="alert"></p></div>`;
}
function renderOrders(){
 const rows=filteredOrders(),shipping=salesTab==='shipping';updatePendingCount();$('resultCount').textContent=rows.length;$('listTitle').firstChild.textContent=shipping?(shippingStage==='pending'?'발송 대기 주문 ':'발송 완료 주문 '):'상품 주문 목록 ';$('listHint').textContent=shipping?(shippingStage==='pending'?'송장번호 입력 후 등록 버튼 또는 Enter로 발송 처리합니다.':'택배사·송장번호를 수정할 수 있습니다. 발송 상태는 유지됩니다.'):'송장 등록·수정은 배송 처리 메뉴에서 진행합니다.';$('shippingStages').hidden=!shipping;$('pageCount').textContent=`${rows.length?'1–'+rows.length:'0'} / ${rows.length}건`;
 $('ordersTable').innerHTML=rows.length?`<table class="orders-table"><thead><tr><th>주문 일시</th><th>주문번호</th><th>구매자</th><th>전화번호</th><th>상품</th><th>수량</th>${shipping?'<th>배송지</th>':'<th>결제금액</th><th>결제 · 환불</th>'}<th>배송 상태</th><th>송장 정보</th><th>상세</th></tr></thead><tbody>${rows.map(o=>`<tr data-number="${esc(o.number)}"><td class="order-date">${esc(dateText(o))}</td><td><b>${esc(o.number)}</b></td><td class="buyer-name"><b>${esc(o.name)}</b></td><td class="buyer-phone">${esc(o.phone)}</td><td class="order-products"><div class="order-cell-lines">${o.items.map(i=>`<span>${esc(i.name)}</span>`).join('')}</div></td><td class="order-quantities"><div class="order-cell-lines">${o.items.map(i=>`<b>${i.qty}</b>`).join('')}</div></td>${shipping?`<td>${esc(o.recipient||o.name)}<small>${esc(o.address)}</small><small>${esc(o.request||'')}</small></td>`:`<td><b>${money(o.total)}</b></td><td><span class="badge ${o.status==='전체 취소'?'grey':''}">${o.status==='전체 취소'?'전액 환불 완료':'결제 완료'}</span></td>`}<td><span class="badge ${o.status==='전체 취소'?'grey':o.status==='출고 완료'||o.status==='배송 완료'?'green':''}">${esc(state(o))}</span></td><td>${invoiceCell(o)}</td><td><button data-detail="${esc(o.number)}">상세보기</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">조건에 맞는 주문이 없습니다.</div>';
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));
 document.querySelectorAll('.invoice-save').forEach(b=>b.onclick=()=>saveRowInvoice(b.closest('tr')));
 document.querySelectorAll('.tracking-input').forEach(input=>input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();saveRowInvoice(input.closest('tr'));}});
}
function saveRowInvoice(row){
 const error=row.querySelector('.invoice-row-error');error.textContent='';
 try{
  const stored=localStorage.getItem('goodsOrders'),latest=stored===null?orderData:JSON.parse(stored);if(!Array.isArray(latest))throw Error('주문 데이터를 확인해 주세요.');
  const order=latest.find(o=>o.number===row.dataset.number);if(!order||!['출고 대기','출고 완료','배송 완료'].includes(order.status))throw Error('현재 상태에서는 송장을 등록할 수 없습니다. 목록을 다시 확인해 주세요.');
  const carrier=row.querySelector('.invoice-carrier').value,trackingNumber=row.querySelector('.tracking-input').value.trim().replace(/[\s-]/g,'');
  if(!carrierNames.includes(carrier))throw Error('택배사를 선택해 주세요.');if(!/^[0-9A-Za-z]{8,30}$/.test(trackingNumber))throw Error('송장번호는 영문·숫자 8~30자리로 입력해 주세요.');
  if(latest.some(o=>o.number!==order.number&&o.status!=='전체 취소'&&o.carrier===carrier&&String(o.trackingNumber||'').replace(/[\s-]/g,'')===trackingNumber))throw Error('다른 주문에 등록된 송장번호입니다.');
  if(order.carrier===carrier&&order.trackingNumber===trackingNumber)return;
  const time=Date.now(),updated=latest.map(o=>o.number===order.number?{...o,carrier,trackingNumber,returnDays:Number(o.returnDays??settings.returnDays)||14,status:o.status==='출고 대기'?'출고 완료':o.status,shippedAt:o.shippedAt||time,shipmentHistory:[...(o.shipmentHistory||[]),{at:time,action:o.trackingNumber?'송장 수정':'송장 등록',previousCarrier:o.carrier||'',previousTrackingNumber:o.trackingNumber||'',carrier,trackingNumber}]}:o);
  localStorage.setItem('goodsOrders',JSON.stringify(updated));orderData=updated;renderOrders();notify('');
 }catch(e){error.textContent=e.message||'저장하지 못했습니다. 다시 시도해 주세요.';}
}
function showDetail(number){detailOrder=orderData.find(o=>o.number===number);const o=detailOrder;if(!o)return;$('orderDetail').innerHTML=`<p><b>${esc(o.number)}</b> <span class="badge">${esc(state(o))}</span></p><p class="form-note">${esc(dateText(o))}</p><section class="detail-section"><h3>주문상품</h3><div class="detail-box">${o.items.map(i=>`<p class="detail-cost"><span>${esc(i.name)} × ${i.qty}</span><b>${i.price!=null?money(i.price*i.qty):'—'}</b></p>`).join('')}</div></section><section class="detail-section"><h3>회원 · 배송정보</h3><div class="detail-box"><p><b>${esc(o.recipient||o.name)}</b> · ${esc(o.recipientPhone||o.phone)}</p><p>${esc(o.address)} ${esc(o.postcode||'')}</p><p>배송메모: ${esc(o.request||'없음')}</p>${o.trackingNumber?`<p>${esc(o.carrier||'택배사 미등록')} · ${esc(o.trackingNumber)}</p>`:''}</div></section>${o.shipmentHistory?.length?`<section class="detail-section"><h3>송장 변경 이력</h3><div class="detail-box">${o.shipmentHistory.map(h=>`<p>${esc(new Date(h.at).toLocaleString('ko-KR'))} · ${esc(h.action)}<br>${h.previousTrackingNumber?esc(h.previousCarrier+' '+h.previousTrackingNumber)+' → ':''}${esc(h.carrier)} · ${esc(h.trackingNumber)}</p>`).join('')}</div></section>`:''}<section class="detail-section"><h3>결제정보</h3><div class="detail-box"><p class="detail-cost"><span>상품금액</span><b>${money(o.subtotal??o.total-(o.shippingFee??settings.shippingFee))}</b></p><p class="detail-cost"><span>배송비</span><b>${money(o.shippingFee??settings.shippingFee)}</b></p><p class="detail-cost total"><span>${o.status==='전체 취소'?'전액 취소금액':'총 결제금액'}</span><b>${money(o.total)}</b></p></div></section><p class="form-note">부분 취소·부분 환불 없이 주문 전체 취소만 가능합니다.</p><div class="dialog-footer"><button data-close="detailDialog">닫기</button>${o.status==='출고 대기'?'<button id="cancelWholeOrder" class="danger">주문 전체 취소</button>':''}</div>`;bindClose();$('cancelWholeOrder')?.addEventListener('click',()=>{if(!confirm('이 주문의 모든 상품을 전액 취소하시겠습니까?'))return;if(o.inventoryApplied!==false)o.items.forEach(i=>{const p=goods.find(p=>p.id===i.id);if(p){p.stock+=i.qty;if(p.status==='soldout')p.status='sale';}});o.status='전체 취소';persist();renderOrders();renderProducts();showDetail(o.number);notify('주문 전체를 취소했습니다.');});if(!$('detailDialog').open)$('detailDialog').showModal();}
$('defaultCarrier').innerHTML=carrierNames.map(c=>`<option ${c===(localStorage.goodsDefaultCarrier||carrierNames[0])?'selected':''}>${c}</option>`).join('');$('defaultCarrier').onchange=()=>{localStorage.goodsDefaultCarrier=$('defaultCarrier').value;document.querySelectorAll('.invoice-carrier').forEach(select=>{const order=orderData.find(o=>o.number===select.closest('tr').dataset.number);if(!order?.trackingNumber)select.value=$('defaultCarrier').value;});};
const adminReturnExample=orderData.find(o=>o.number==='G-260911-0002');
if(adminReturnExample&&!adminReturnExample.returnStatus)Object.assign(adminReturnExample,{status:'배송 완료',returnStatus:'신청 완료',returnReason:'단순 변심',returnDetail:'상품을 확인했으나 생각했던 크기와 달라 전체 반품을 요청합니다.',returnMethod:'고객 직접 반송(착불)',returnRequestedAt:Date.now()-86400000});
orderData.forEach(order=>{if(order.returnStatus&&['수거 접수','직접 발송'].includes(order.returnMethod))order.returnMethod='고객 직접 반송(착불)';});
localStorage.goodsOrders=JSON.stringify(orderData);
if(!$('paymentFilter').querySelector('[value="return_requested"]'))$('paymentFilter').querySelector('[value="cancelled"]').insertAdjacentHTML('beforebegin','<option value="return_requested">반품 신청 완료</option><option value="refunded">환불 완료</option>');
if(!$('shippingFilter').querySelector('[value="배송 완료"]'))$('shippingFilter').insertAdjacentHTML('beforeend','<option value="배송 완료">배송 완료</option>');

function paymentLabel(order){return order.status==='전체 취소'?'전액 환불 완료':order.returnStatus==='환불 완료'?'환불 완료':order.returnStatus==='신청 완료'?'반품 신청 완료':'결제 완료';}
filteredOrders=function(){const keyword=$('keyword').value.trim().toLowerCase(),payment=$('paymentFilter').value,ship=$('shippingFilter').value;return orderData.filter(o=>{const date=o.createdAt?new Date(o.createdAt):null,day=date?`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`:'';const paymentMatch=!payment||(payment==='cancelled'?o.status==='전체 취소':payment==='return_requested'?o.returnStatus==='신청 완료':payment==='refunded'?o.returnStatus==='환불 완료':payment==='paid'?o.status!=='전체 취소'&&!o.returnStatus:true),searchText=[o.number,o.name,o.phone,o.recipient,...(o.items||[]).map(item=>item.name)].join(' ').toLowerCase();return (salesTab!=='shipping'||(shippingStage==='pending'?o.status==='출고 대기':['출고 완료','배송 완료'].includes(o.status)))&&(!keyword||searchText.includes(keyword))&&paymentMatch&&(!ship||o.status===ship)&&(!$('startDate').value||day>=$('startDate').value)&&(!$('endDate').value||day<=$('endDate').value);});};

